/bin/bash -lc "python3 << 'PY'
import json
from pathlib import Path

questions = [
    {
        \"id\": \"p_aba\",
        \"prompt\": \"Write Python 3 "'`solve(s: str) -> bool`. Return True iff s is exactly 9 digits and the weighted sum is divisible by 10. Digit i (0-based) is multiplied by weight[i], where weight = [3, 7, 1, 3, 7, 1, 3, 7, 1]. Reject any other character, including spaces and hyphens. Return only one fenced python block.",
    },
    {
        "id": "p_ean8",
        "prompt": "Write Python 3 `solve(s: str) -> bool`. Return True iff s is exactly 8 digits and the alternating sum is divisible by 10. Digit i (0-based) is multiplied by 3 if i is even and by 1 if i is odd. Reject any non-digit. Return only one fenced python block.",
    },
    {
        "id": "p_upc",
        "prompt": "Write Python 3 `solve(s: str) -> bool`. Remove spaces and hyphens, then return True iff the remaining text is exactly 12 digits and the weighted sum is divisible by 10. Digit i (0-based) is multiplied by 3 if i is even and by 1 if i is odd. Return only one fenced python block.",
    },
    {
        "id": "p_cusip",
        "prompt": "Write Python 3 `solve(s: str) -> bool`. Return True iff s is a valid 9-character code after removing spaces and hyphens. The remaining text must be 8 alphanumeric characters plus a final digit. Letters are case-insensitive and valued A=10 through Z=35. For each of the first 8 characters, take its value and double it when the 0-based index is odd. If a value is above 9, replace it by the sum of its decimal digits. Add the eight results. The check digit is (10 - (total % 10)) % 10 and must equal the final character. Return only one fenced python block.",
    },
    {
        "id": "p_lib",
        "prompt": "Write Python 3 `solve(s: str) -> bool`. Return True iff s is a valid library code after removing hyphens and spaces. The remaining text has length 8. The first 7 characters are digits. The last character is a digit or X, case-insensitive. Let check be 10 if the last character is X, otherwise its digit. Compute total = d0*8 + d1*7 + d2*6 + d3*5 + d4*4 + d5*3 + d6*2 + check. The code is valid iff total % 11 == 0. Return only one fenced python block.",
    },
    {
        "id": "p_sedol",
        "prompt": "Write Python 3 `solve(s: str) -> bool`. Return True iff s is exactly 7 characters with no separators. The first 6 characters are digits or consonants (letters other than A, E, I, O, U), case-insensitive. The last character is a digit. Letter values are A=10 through Z=35. Weights for the first 6 characters are 1, 3, 1, 7, 3, 9. The check digit is (10 - (weighted sum % 10)) % 10 and must equal the last character. Return only one fenced python block.",
    },
    {
        "id": "p_window",
        "prompt": "Write Python 3 `solve(nums: list[int], k: int) -> list[int]`. Return the maximum of every contiguous window of length k, from left to right. Assume 1 <= k <= len(nums). Example: solve([1, 3, -1, -3, 5, 3, 6, 7], 3) returns [3, 3, 5, 5, 6, 7]. Return only one fenced python block.",
    },
    {
        "id": "p_merge",
        "prompt": "Write Python 3 `solve(intervals: list[list[int]]) -> list[list[int]]`. Each interval is an inclusive [start, end]. Merge overlapping or touching intervals and return them sorted by start. An empty list returns []. Example: [[1, 3], [2, 6], [8, 10], [15, 18]] returns [[1, 6], [8, 10], [15, 18]]. Touching intervals such as [[1, 2], [2, 3]] merge to [[1, 3]]. Return only one fenced python block.",
    },
]

impl = {
    "p_aba": {"tests": [
        [["000000000"], True], [["000000013"], True], [["000000026"], True],
        [["000000014"], False], [["00000000"], False], [["0000000001"], False],
        [["00000001A"], False], [[" 000000000"], False], [["000-000000"], False],
    ]},
    "p_ean8": {"tests": [
        [["10000007"], True], [["10000014"], True], [["10000021"], True],
        [["10000008"], False], [["1000000"], False], [["100000070"], False],
        [["1000000A"], False], [["1000 0007"], False],
    ]},
    "p_upc": {"tests": [
        [["100000000007"], True], [["100000000014"], True],
        [["1000-0000-0007"], True], [["1000 0000 0014"], True],
        [["100000000008"], False], [["10000000000"], False],
        [["1000000000071"], False], [["10000000000A"], False],
    ]},
    "p_cusip": {"tests": [
        [["037833100"], True], [["G12345008"], True], [["b00000016"], True],
        [["0378-3310-0"], True], [["0378 3310 0"], True],
        [["037833101"], False], [["03783310"], False], [["0378331000"], False],
        [["03783310A"], False], [["03783310!"], False],
    ]},
    "p_lib": {"tests": [
        [["00000000"], True], [["00000175"], True], [["00000345"], True],
        [["0000006X"], True], [["0000-0000"], True], [["0000 0175"], True],
        [["0000006x"], True], [["00000176"], False], [["0000017"], False],
        [["000001755"], False], [["0000017Y"], False],
    ]},
    "p_sedol": {"tests": [
        [["0002341"], True], [["B002340"], True], [["bc00003"], True],
        [["12345B8"], True], [["0002342"], False], [["000234"], False],
        [["00023411"], False], [["A002341"], False], [["E000001"], False],
        [["00023-1"], False],
    ]},
    "p_window": {"tests": [
        [[[1, 3, -1, -3, 5, 3, 6, 7], 3], [3, 3, 5, 5, 6, 7]],
        [[[4], 1], [4]],
        [[[1, 2, 3], 3], [3]],
        [[[5, 1, 4, 2], 2], [5, 4, 4]],
        [[[-2, -1, -3], 1], [-2, -1, -3]],
        [[[9, 8, 7, 6, 5], 4], [9, 8]],
    ]},
    "p_merge": {"tests": [
        [[[[1, 3], [2, 6], [8, 10], [15, 18]]], [[1, 6], [8, 10], [15, 18]]],
        [[[[1, 2], [2, 3]]], [[1, 3]]],
        [[[[1, 4], [0, 2]]], [[0, 4]]],
        [[[[]], []], []],
        [[[[5, 5]]], [[5, 5]]],
        [[[[1, 2], [4, 5], [3, 3]]], [[1, 2], [3, 3], [4, 5]]],
        [[[[10, 12], [1, 3], [2, 4]]], [[1, 4], [10, 12]]],
    ]},
}

sols = {
"p_aba": '"'''
def solve(s):
    if len(s) "'!= 9 or not s.isdigit():
        return False
    w = [3, 7, 1, 3, 7, 1, 3, 7, 1]
    return sum(int(ch) * w[i] for i, ch in enumerate(s)) % 10 == 0
'"''',
\"p_ean8\": '''
def solve(s):
    if len(s) "'!= 8 or not s.isdigit():
        return False
    return sum(int(ch) * (3 if i % 2 == 0 else 1) for i, ch in enumerate(s)) % 10 == 0
'"''',
\"p_upc\": '''
def solve(s):
    s = s.replace(\" \", \"\").replace(\"-\", \"\")
    if len(s) "'!= 12 or not s.isdigit():
        return False
    return sum(int(ch) * (3 if i % 2 == 0 else 1) for i, ch in enumerate(s)) % 10 == 0
'"''',
\"p_cusip\": '''
def solve(s):
    s = s.replace(\" \", \"\").replace(\"-\", \"\").upper()
    if len(s) "'!= 9 or not s[:8].isalnum() or not s[8].isdigit():
        return False
    def val(ch):
        return int(ch) if ch.isdigit() else ord(ch) - ord("A") + 10
    total = 0
    for i, ch in enumerate(s[:8]):
        v = val(ch)
        if i % 2 == 1:
            v *= 2
        if v > 9:
            v = v // 10 + v % 10
        total += v
    return int(s[8]) == (10 - (total % 10)) % 10
'"''',
\"p_lib\": '''
def solve(s):
    s = s.replace(\"-\", \"\").replace(\" \", \"\").upper()
    if len(s) "'!= 8 or not s[:7].isdigit() or not (s[7].isdigit() or s[7] == "X"):
        return False
    check = 10 if s[7] == "X" else int(s[7])
    total = sum(int(s[i]) * (8 - i) for i in range(7)) + check
    return total % 11 == 0
'"''',
\"p_sedol\": '''
def solve(s):
    if len(s) "'!= 7 or not s[6].isdigit():
        return False
    body = s[:6].upper()
    vowels = set("AEIOU")
    for ch in body:
        if not (ch.isdigit() or (ch.isalpha() and ch not in vowels)):
            return False
    def val(ch):
        return int(ch) if ch.isdigit() else ord(ch) - ord("A") + 10
    weights = [1, 3, 1, 7, 3, 9]
    total = sum(val(ch) * weights[i] for i, ch in enumerate(body))
    return int(s[6]) == (10 - (total % 10)) % 10
'"''',
\"p_window\": '''
def solve(nums, k):
    return [max(nums[i:i+k]) for i in range(len(nums) - k + 1)]
''',
\"p_merge\": '''
def solve(intervals):
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda x: (x[0], x[1]))
    out = [list(intervals[0])]
    for a, b in intervals[1:]:
        if a <= out[-1][1]:
            out[-1][1] = max(out[-1][1], b)
        else:
            out.append([a, b])
    return out
''',
}

for iid, code in sols.items():
    ns = {}
    exec(code, ns, ns)
    solve = ns[\"solve\"]
    for args, expected in impl[iid][\"tests\"]:
        got = solve(*args)
        if got "'!= expected:
            print("FAIL", iid, args, "got", got, "expected", expected)
            raise SystemExit(1)
print("refs ok")

# also run through submission run_impl to match grader normalization
import sys
sys.path.insert(0, "/workspace")
# import run module functions without executing main
import importlib.util
specm = importlib.util.spec_from_file_location("subrun", "/workspace/submission/run.py")
mod = importlib.util.module_from_spec(specm)
specm.loader.exec_module(mod)
for iid, code in sols.items():
    fenced = "```python'"\\n\" + code + \"\\n"'```"
    # temporarily point SPEC
    mod.SPEC = {"impl": impl, "traces": {}, "answers": {}, "checks": {}, "tokens": {}}
    result = mod.grade_impl(iid, fenced)
    print(iid, result["score"], result.get("passed"), result.get("n"))
    if result["score"] != 1.0:
        raise SystemExit("grader mismatch " + iid)

tokens = {q["id"]: 1536 for q in questions}
spec_out = {"impl": impl, "traces": {}, "answers": {}, "checks": {}, "tokens": tokens}
root = Path("/workspace/pilot_sep")
(root / "grader_spec.json").write_text(json.dumps(spec_out))
items = [{"id": q["id"], "question_id": q["id"], "domain": "coding"} for q in questions]
n = len(questions)
w = {q["id"]: 1.0 / n for q in questions}
ev = {
    "protocol_version": 1,
    "selection": "fixed",
    "questions": questions,
    "items": items,
    "aggregation": {"kind": "weighted_mean"},
    "domain_aggregations": {
        "coding": {"kind": "weighted_mean", "weights": w},
        "co-work": {"kind": "weighted_mean", "weights": w},
        "reasoning": {"kind": "weighted_mean", "weights": w},
    },
}
(root / "evaluation.json").write_text(json.dumps(ev, indent=2) + "'"\\n\")
(root / \"README.md\").write_text(\"Separator pilot. Same local grader and system prompt as the frozen suite. Cap 1536.\\n\")
print(\"wrote pilot\", n)
PY"

