    pm={q[\"id\"]:q[\"prompt\"] for q in ev[\"questions\"]}
    print(\"====\", name)
    for iid in [\"c_halfup\",\"c_touch\",\"c_second\",\"c_cidr\",\"c_depth\",\"c_minutes\",\"tr_tr16\",\"tr_tr20\",\"w_if_close\",\"w_if_hold\"]:
        if iid not in pm:
            print(iid, \"absent\")
            continue
        same = pm[iid]==fp.get(iid)
        print(iid, \"SAME\" if same else \"DIFF\", \"sub_cap\", json.loads(Path(\"/workspace/submission/grader_spec.json\").read_text())[\"tokens\"].get(iid), \"probe_cap\", json.loads(Path(f\"/workspace/probe_{name}/grader_spec.json\").read_text())[\"tokens\"].get(iid))
        if not same:
            print(\" PROBE\", pm[iid][:220].replace(\"\\n\",\" \"))
            print(\" FINAL\", (fp.get(iid) or \"\")[:220].replace(\"\\n\",\" \"))
